async (page) => {
  const res = {};
  let cur = null;
  const onErr = e => { (res[cur] ||= []).push('exception: ' + e.message); };
  const onCon = m => { if (m.type()==='error') (res[cur] ||= []).push('console: ' + m.text()); };
  page.on('pageerror', onErr); page.on('console', onCon);
  for (const l of 'ABCDEFGH') {
    cur = l; res[l] = [];
    const r = page.waitForResponse(x => x.url().includes('api/run/' + l));
    await page.click(`button[data-l="${l}"]`);
    const resp = await r;
    res[l].push('body: ' + await resp.text());
    await page.waitForTimeout(1200);
  }
  page.off('pageerror', onErr); page.off('console', onCon);
  return res;
}

